}

default
{
touch_start
(
integer
num_detected
)
{
integer
link
=
llDetectedLinkNumber
(
0
);
integer
face
=
llDetectedTouchFace
(
0
);
if
(
face
==
TOUCH_INVALID_FACE
)
llSay
(
PUBLIC_CHANNEL
,
"Sorry, your viewer doesn't support touched faces."
);
else
{
// store the original color
list
colorParams
=
llGetLinkPrimitiveParams
(
link
,
[
PRIM_COLOR
,
face
]);
vector
originalColor
=
llList2Vector
(
colorParams
,
0
);
// color detected face white
llSetLinkColor
(
link
,
<
1.0
,
1.0
,
1.0
>
,
face
);
llSleep
(
0.2
);
// color detected face black
llSetLinkColor
(
link
,
ZERO_VECTOR
,
face
);
llSleep
(
0.2
);
// color detected face back to original color
llSetLinkColor
(
link
,
originalColor
,
face
);
}
}
}
